class="dx-tm-title">这一类今天没有任务</div></div></div>'}
    else{
      var out=[],curSub='',curChap='';
      sel.forEach(function(t,i){
        var isS=t.kind==='sports';
        var sub=isS?(t.subject||'综合'):((t.kind==='vocab'||t.kind==='phrase'||t.kind==='sentence')?'英语单词/短语':(t.cat||'其他'));
        if(sub!==curSub){curSub=sub;curChap='';out.push('<div class="dx-tm-sub">'+esc(sub)+'</div>')}
        if(isS){var cp=chapText(t);if(cp!==curChap){curChap=cp;out.push('<div class="dx-tm-chap">'+esc(cp)+'</div>')}}
        out.push('<div class="dx-tm-row" onclick="dxTodayGo('+i+')"><div class="dx-tm-idx">'+(i+1)+'</div><div class="dx-tm-main"><div class="dx-tm-title">'+esc(t.title)+'<span class="dx-tm-tag">'+esc(t.priority||'')+'</span><span class="dx-tm-tag">'+st(t)+'</span></div><div class="dx-tm-meta">'+esc(t.meta||'')+'</div></div></div>');
      });
      body.innerHTML=out.join('');
    }
    var m=document.getElementById('dx-today');m.classList.add('on');body.scrollTop=0;
  };
})();
</script>
</body>
